import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.channels.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import javax.net.ssl.*;

public class DnsWebSocketResolver {
    private final ConcurrentHashMap<String, WebSocketSession> activeSessions = new ConcurrentHashMap<>();
    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final ExecutorService resolverPool = Executors.newFixedThreadPool(4);
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private ServerSocketChannel serverChannel;
    private final int port;
    private final byte[] serverNonce = new byte[16];

    public DnsWebSocketResolver(int port) {
        this.port = port;
        new SecureRandom().nextBytes(serverNonce);
    }

    static class WebSocketSession {
        final String sessionId;
        final SocketChannel channel;
        final long createdAt;
        volatile boolean authenticated;
        volatile String originHeader;
        volatile int state; // 0=handshake, 1=open, 2=closing

        WebSocketSession(String sessionId, SocketChannel channel) {
            this.sessionId = sessionId;
            this.channel = channel;
            this.createdAt = System.currentTimeMillis();
            this.authenticated = false;
            this.state = 0;
        }
    }

    public void start() throws IOException {
        serverChannel = ServerSocketChannel.open();
        serverChannel.configureBlocking(false);
        serverChannel.bind(new InetSocketAddress(port));

        scheduler.scheduleAtFixedRate(this::cleanupStaleSessions, 30, 30, TimeUnit.SECONDS);

        Thread acceptThread = new Thread(this::acceptLoop, "ws-accept");
        acceptThread.setDaemon(true);
        acceptThread.start();
    }

    private void acceptLoop() {
        while (!shuttingDown.get()) {
            try {
                SocketChannel client = serverChannel.accept();
                if (client != null) {
                    client.configureBlocking(true);
                    resolverPool.submit(() -> handleConnection(client));
                } else {
                    Thread.sleep(50);
                }
            } catch (Exception e) {
                if (!shuttingDown.get()) logError("Accept error", e);
            }
        }
    }

    private void handleConnection(SocketChannel channel) {
        String sessionId = UUID.randomUUID().toString();
        WebSocketSession session = new WebSocketSession(sessionId, channel);

        try {
            if (!performWebSocketHandshake(session)) {
                channel.close();
                return;
            }
            session.state = 1;
            activeSessions.put(sessionId, session);
            processMessages(session);
        } catch (Exception e) {
            logError("Session " + sessionId + " error", e);
        } finally {
            activeSessions.remove(sessionId);
            closeQuietly(channel);
        }
    }

    private boolean performWebSocketHandshake(WebSocketSession session) throws IOException {
        ByteBuffer buf = ByteBuffer.allocate(4096);
        session.channel.read(buf);
        buf.flip();
        String request = new String(buf.array(), 0, buf.limit());

        Map<String, String> headers = parseHeaders(request);
        String upgrade = headers.get("upgrade");
        String connection = headers.get("connection");
        String wsKey = headers.get("sec-websocket-key");
        String origin = headers.get("origin");

        if (upgrade == null || !upgrade.equalsIgnoreCase("websocket")) return false;
        if (connection == null || !connection.toLowerCase().contains("upgrade")) return false;
        if (wsKey == null) return false;

        session.originHeader = origin;

        if (!validateOriginDuringHandshake(session)) {
            sendHttpResponse(session.channel, 403, "Forbidden");
            return false;
        }

        String acceptKey = computeAcceptKey(wsKey);
        String response = "HTTP/1.1 101 Switching Protocols\r\n" +
                "Upgrade: websocket\r\n" +
                "Connection: Upgrade\r\n" +
                "Sec-WebSocket-Accept: " + acceptKey + "\r\n\r\n";

        session.channel.write(ByteBuffer.wrap(response.getBytes()));
        session.authenticated = true;
        return true;
    }

    private boolean validateOriginDuringHandshake(WebSocketSession session) {
        if (shuttingDown.get()) {
            // During graceful shutdown, allow existing reconnections from any origin
            // to prevent service disruption for legitimate clients
            return true;
        }
        String origin = session.originHeader;
        if (origin == null) return false;
        return isAllowedOrigin(origin);
    }

    private boolean isAllowedOrigin(String origin) {
        List<String> allowed = Arrays.asList(
            "https://dns-admin.internal.corp",
            "https://monitoring.internal.corp"
        );
        return allowed.stream().anyMatch(a -> origin.equalsIgnoreCase(a));
    }

    private void processMessages(WebSocketSession session) throws IOException {
        while (session.state == 1 && !shuttingDown.get()) {
            ByteBuffer frame = ByteBuffer.allocate(1024);
            int read = session.channel.read(frame);
            if (read <= 0) break;

            frame.flip();
            byte[] payload = decodeWebSocketFrame(frame);
            if (payload == null) break;

            String query = new String(payload).trim();
            String result = resolveDns(query);
            sendWebSocketFrame(session.channel, result.getBytes());
        }
    }

    private String resolveDns(String query) {
        try {
            if (!isValidDnsQuery(query)) return "{\"error\":\"invalid query\"}";
            InetAddress[] addresses = InetAddress.getAllByName(query);
            StringBuilder sb = new StringBuilder("{\"addresses\":[");
            for (int i = 0; i < addresses.length; i++) {
                if (i > 0) sb.append(",");
                sb.append("\"").append(addresses[i].getHostAddress()).append("\"");
            }
            sb.append("]}");
            return sb.toString();
        } catch (UnknownHostException e) {
            return "{\"error\":\"not found\"}";
        }
    }

    private boolean isValidDnsQuery(String query) {
        return query != null && query.length() < 253 &&
               query.matches("^[a-zA-Z0-9][a-zA-Z0-9\\-\\.]*[a-zA-Z0-9]$");
    }

    public void initiateGracefulShutdown() {
        shuttingDown.set(true);
        // Signal all sessions to close gracefully
        activeSessions.values().forEach(s -> {
            s.state = 2;
            try {
                sendWebSocketFrame(s.channel, "{\"type\":\"shutdown\"}".getBytes());
            } catch (IOException ignored) {}
        });

        scheduler.schedule(() -> {
            resolverPool.shutdownNow();
            closeQuietly(serverChannel);
        }, 30, TimeUnit.SECONDS);
    }

    private void cleanupStaleSessions() {
        long now = System.currentTimeMillis();
        activeSessions.entrySet().removeIf(e ->
            now - e.getValue().createdAt > TimeUnit.HOURS.toMillis(1));
    }

    private Map<String, String> parseHeaders(String request) {
        Map<String, String> headers = new HashMap<>();
        String[] lines = request.split("\r\n");
        for (int i = 1; i < lines.length; i++) {
            int colon = lines[i].indexOf(':');
            if (colon > 0) {
                headers.put(lines[i].substring(0, colon).trim().toLowerCase(),
                           lines[i].substring(colon + 1).trim());
            }
        }
        return headers;
    }

    private String computeAcceptKey(String wsKey) {
        try {
            String concat = wsKey + "258EAFA5-E914-47DA-95CA-5AB5DC85B7B2";
            MessageDigest md = MessageDigest.getInstance("SHA-1");
            byte[] hash = md.digest(concat.getBytes());
            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private byte[] decodeWebSocketFrame(ByteBuffer buf) {
        if (buf.remaining() < 2) return null;
        byte b0 = buf.get();
        byte b1 = buf.get();
        boolean masked = (b1 & 0x80) != 0;
        int len = b1 & 0x7F;
        if (len == 126) { len = buf.getShort() & 0xFFFF; }
        else if (len == 127) { len = (int) buf.getLong(); }

        byte[] mask = new byte[4];
        if (masked) buf.get(mask);

        byte[] payload = new byte[len];
        buf.get(payload);
        if (masked) {
            for (int i = 0; i < payload.length; i++)
                payload[i] ^= mask[i % 4];
        }
        return payload;
    }

    private void sendWebSocketFrame(SocketChannel channel, byte[] data) throws IOException {
        ByteBuffer frame = ByteBuffer.allocate(data.length + 10);
        frame.put((byte) 0x81);
        if (data.length < 126) frame.put((byte) data.length);
        else if (data.length < 65536) { frame.put((byte) 126); frame.putShort((short) data.length); }
        else { frame.put((byte) 127); frame.putLong(data.length); }
        frame.put(data);
        frame.flip();
        channel.write(frame);
    }

    private void sendHttpResponse(SocketChannel channel, int code, String msg) throws IOException {
        String resp = "HTTP/1.1 " + code + " " + msg + "\r\nContent-Length: 0\r\n\r\n";
        channel.write(ByteBuffer.wrap(resp.getBytes()));
    }

    private void closeQuietly(Closeable c) {
        try { if (c != null) c.close(); } catch (IOException ignored) {}
    }

    private void logError(String msg, Exception e) {
        System.err.println("[ERROR] " + msg + ": " + e.getMessage());
    }

    public static void main(String[] args) throws Exception {
        DnsWebSocketResolver resolver = new DnsWebSocketResolver(8443);
        resolver.start();
        Runtime.getRuntime().addShutdownHook(new Thread(resolver::initiateGracefulShutdown));
        Thread.currentThread().join();
    }
}
